"""Ground-truth dump of a RoboDK file using RoboDK itself.

    python dump_gt.py <file.rdk|.robot|.tool> <out.json> <port> <codedir>

Records the item tree, robot kinematics (FK samples), tools, targets, program instructions,
program validity / cycle time (Item.Update), simulated joint lists (InstructionListJoints)
and the code generated by the robot's post processor (MakeProgram).
"""
import sys, os, json, time, random, traceback
sys.path.insert(0, r'C:\RoboDK\Python')
from robodk.robolink import *
from robodk.robomath import *

src, out, port, codedir = sys.argv[1], sys.argv[2], int(sys.argv[3]), sys.argv[4]
T0 = time.time()
res = {'file': src, 'errors': []}


def mat16(m):
    try:
        return [round(float(v), 6) for row in m.rows for v in row] if m is not None else None
    except Exception:
        return None


def jl(m):
    try:
        if m is None:
            return None
        return [round(float(v), 6) for v in m.list()]
    except Exception:
        try:
            return [round(float(v), 6) for v in m]
        except Exception:
            return None


def safe(fn, default=None, tag=''):
    try:
        return fn()
    except Exception as e:
        if tag:
            res['errors'].append('%s: %s' % (tag, str(e)[:200]))
        return default


RDK = Robolink(args=['-NOSPLASH', '-HIDDEN', '-NEWINSTANCE', '-NOUI'], port=port)
res['version'] = safe(RDK.Version, '')
loaded = RDK.AddFile(src)
res['load_time'] = round(time.time() - T0, 2)
res['loaded'] = bool(loaded.Valid())
station = RDK.ActiveStation()
if loaded.Valid() and safe(loaded.Type) == ITEM_TYPE_STATION:
    station = loaded
    safe(lambda: RDK.setActiveStation(loaded))
res['station'] = safe(station.Name, '')

items = []
ids = {}


def walk(it, parent_name, depth):
    for c in safe(it.Childs, [], 'childs') or []:
        d = {
            'id': c.item, 'type': safe(c.Type, -1), 'name': safe(c.Name, ''), 'parent': parent_name,
            'pose': mat16(safe(c.Pose)), 'poseAbs': mat16(safe(c.PoseAbs)), 'visible': safe(c.Visible, None),
        }
        items.append(d)
        ids[c.item] = d
        if depth < 30:
            walk(c, d['name'], depth + 1)


walk(station, res['station'], 0)
res['items'] = items

# Robots / mechanisms
robots = []
rng = random.Random(1234)
for r in RDK.ItemList(ITEM_TYPE_ROBOT):
    rd = {'name': safe(r.Name, ''), 'parent': safe(lambda: r.Parent().Name(), '')}
    j = safe(r.Joints)
    rd['joints'] = jl(j)
    rd['jointsHome'] = jl(safe(r.JointsHome))
    lim = safe(r.JointLimits)
    if lim:
        rd['lower'] = jl(lim[0])
        rd['upper'] = jl(lim[1])
        rd['jointsType'] = safe(lambda: float(lim[2]))
    rd['poseTool'] = mat16(safe(r.PoseTool))
    rd['poseFrame'] = mat16(safe(r.PoseFrame))
    rd['poseAbs'] = mat16(safe(r.PoseAbs))
    rd['fkCurrent'] = mat16(safe(lambda: r.SolveFK(j))) if j is not None else None
    rd['postProcessor'] = safe(lambda: r.getParam('PostProcessor'), None)
    rd['tools'] = [safe(t.Name, '') for t in (safe(r.Childs, []) or []) if safe(t.Type) == ITEM_TYPE_TOOL]
    samples = []
    if rd.get('lower') and rd.get('upper'):
        n = len(rd['lower'])
        for k in range(12):
            q = []
            for a in range(n):
                lo, hi = rd['lower'][a], rd['upper'][a]
                lo, hi = max(lo, -360.0), min(hi, 360.0)
                q.append(round(lo + (hi - lo) * rng.random(), 4))
            # FK of flange without tool and without reference: robot base frame
            f = safe(lambda: r.SolveFK(q, eye(4), eye(4)), None, 'fk')
            ft = safe(lambda: r.SolveFK(q), None, 'fk2')
            samples.append({'q': q, 'flange': mat16(f), 'tcpInFrame': mat16(ft)})
    rd['fk'] = samples
    # IK of current pose: all solutions (configuration handling)
    if j is not None:
        allsol = safe(lambda: r.SolveIK_All(r.SolveFK(j)))
        def _count(a):
            try:
                return a.size(1)
            except Exception:
                try:
                    return len(a)
                except Exception:
                    return None
        rd['ikAllCount'] = _count(allsol) if allsol is not None else None
        rd['jointsConfig'] = jl(safe(lambda: r.JointsConfig(j)))
    robots.append(rd)
res['robots'] = robots

# Tools
tools = []
for t in RDK.ItemList(ITEM_TYPE_TOOL):
    tools.append({'name': safe(t.Name, ''), 'parent': safe(lambda: t.Parent().Name(), ''), 'poseTool': mat16(safe(t.PoseTool)),
                  'pose': mat16(safe(t.Pose))})
res['tools'] = tools

# Targets
targets = []
for t in RDK.ItemList(ITEM_TYPE_TARGET):
    targets.append({'name': safe(t.Name, ''), 'parent': safe(lambda: t.Parent().Name(), ''), 'pose': mat16(safe(t.Pose)),
                    'joints': jl(safe(t.Joints)), 'isJoint': safe(t.isJointTarget, None),
                    'robot': safe(lambda: t.getLink(ITEM_TYPE_ROBOT).Name(), '')})
res['targets'] = targets

# Other item types summary
res['objects'] = [{'name': safe(o.Name, ''), 'parent': safe(lambda: o.Parent().Name(), ''), 'poseAbs': mat16(safe(o.PoseAbs))}
                  for o in RDK.ItemList(ITEM_TYPE_OBJECT)]
res['frames'] = [{'name': safe(o.Name, ''), 'parent': safe(lambda: o.Parent().Name(), ''), 'pose': mat16(safe(o.Pose))}
                 for o in RDK.ItemList(ITEM_TYPE_FRAME)]
res['python'] = [{'name': safe(o.Name, ''), 'parent': safe(lambda: o.Parent().Name(), '')} for o in RDK.ItemList(ITEM_TYPE_PROGRAM_PYTHON)]
res['machining'] = []
for m in RDK.ItemList(ITEM_TYPE_MACHINING):
    md = {'name': safe(m.Name, ''), 'program': safe(lambda: m.getLink(ITEM_TYPE_PROGRAM).Name(), ''),
          'robot': safe(lambda: m.getLink(ITEM_TYPE_ROBOT).Name(), '')}
    md['update'] = safe(lambda: list(m.Update()), None, 'machining update ' + md['name'])
    res['machining'].append(md)
res['curves'] = [safe(o.Name, '') for o in RDK.ItemList(ITEM_TYPE_CURVE)]
res['cameras'] = [safe(o.Name, '') for o in RDK.ItemList(ITEM_TYPE_CAMERA)]

# Programs
progs = []
os.makedirs(codedir, exist_ok=True)
for p in RDK.ItemList(ITEM_TYPE_PROGRAM):
    name = safe(p.Name, '')
    pd = {'name': name, 'robot': safe(lambda: p.getLink(ITEM_TYPE_ROBOT).Name(), '')}
    n = safe(p.InstructionCount, 0) or 0
    pd['count'] = n
    ins = []
    for i in range(min(n, 3000)):
        x = safe(lambda: p.Instruction(i))
        if not x:
            ins.append(None)
            continue
        nm, it, mt, isj, pose, joints = x
        ins.append({'name': nm, 'type': it, 'move': mt, 'isJoint': isj, 'pose': mat16(pose) if pose is not None else None,
                    'joints': jl(joints) if joints is not None else None})
    pd['instructions'] = ins
    t1 = time.time()
    pd['update'] = safe(lambda: list(p.Update(COLLISION_OFF, 600)), None, 'update ' + name)
    # DUMP_NO_COLLISION=1: skip the collision-checked update (hours for the long machining programs of 02.f turntable)
    pd['updateCollision'] = None if os.environ.get('DUMP_NO_COLLISION') else safe(lambda: list(p.Update(COLLISION_ON, 600)), None, 'updateC ' + name)
    msg_code = safe(lambda: p.InstructionListJoints(5, 5, None, COLLISION_OFF, 1, 0.1), None, 'joints ' + name)
    if msg_code:
        msg, mat, status = msg_code
        pd['jlMsg'] = msg
        pd['jlStatus'] = status
        rows = []
        try:
            rws = getattr(mat, 'rows', None)
            steps = [list(c) for c in zip(*rws)] if rws and isinstance(rws[0], list) else []
            pd['jlSteps'] = len(steps)
            # keep the last step of every MOVE_ID and every 20th step
            last = {}
            for k, s in enumerate(steps):
                dof = len(s) - 8  # J1..Jn, ERROR, MM_STEP, DEG_STEP, MOVE_ID, TIME, X, Y, Z
                mid = s[dof + 3]
                last[mid] = k
            keep = set(last.values()) | set(range(0, len(steps), 20)) | ({len(steps) - 1} if steps else set())
            for k in sorted(keep):
                rows.append([round(float(v), 4) for v in steps[k]])
        except Exception as e:
            res['errors'].append('jl parse %s: %s' % (name, e))
        pd['jl'] = rows
    pd['simTime'] = round(time.time() - t1, 2)
    # generated code with the robot post processor
    pdir = os.path.join(codedir, ''.join(ch if ch.isalnum() or ch in '-_' else '_' for ch in name))
    os.makedirs(pdir, exist_ok=True)
    # DUMP_NO_MAKE=1: skip code generation (the hidden Fanuc post of 03.g blocks RoboDK until the API times out)
    mk = None if os.environ.get('DUMP_NO_MAKE') else safe(lambda: p.MakeProgram(pdir), None, 'make ' + name)
    pd['make'] = list(mk) if mk else None
    pd['codeFiles'] = sorted(os.listdir(pdir)) if os.path.isdir(pdir) else []
    progs.append(pd)
res['programs'] = progs
res['elapsed'] = round(time.time() - T0, 2)
with open(out, 'w', encoding='utf-8') as f:
    json.dump(res, f, default=lambda o: o.decode('latin1') if isinstance(o, bytes) else str(o))
print('OK', src, 'items', len(items), 'robots', len(robots), 'programs', len(progs), 'errors', len(res['errors']), res['elapsed'], 's', flush=True)
try:
    RDK.CloseRoboDK()
except Exception:
    pass
